const B="";const I=Uint8Array.from(atob(B),c=>c.charCodeAt(0));const H={'content-type':'image/webp','cache-control':'public,max-age=31536000,immutable','access-control-allow-origin':'*'};
const originalHandler=r=>r.method==='HEAD'?new Response(null,{headers:H}):r.method==='GET'?new Response(I,{headers:H}):new Response('Method Not Allowed',{status:405});
const COVER_B64="";
let coverBytes:Uint8Array|undefined;
Deno.serve((req:Request)=>{const k=new URL(req.url).searchParams.get('cover');if(k===null)return originalHandler(req);if(k!=="quantum")return new Response('Cover not found',{status:404});if(req.method!=='GET'&&req.method!=='HEAD')return new Response('Method Not Allowed',{status:405,headers:{Allow:'GET, HEAD'}});coverBytes??=Uint8Array.from(atob(COVER_B64),c=>c.charCodeAt(0));return new Response(req.method==='HEAD'?null:coverBytes,{headers:{'content-type':'image/png','content-length':String(coverBytes.byteLength),'cache-control':'public,max-age=86400','access-control-allow-origin':'*','x-content-type-options':'nosniff'}});});